  'Platform' => 'Платформа',
  'Playback' => 'Ойнотуу',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Ойнотуу процесси, кийинчерээк көрүү абалы, жактыруулар, жорумдар, жазылуулар, эскертмелер жана администратордун аналитикасы аныктыгы тастыкталган платформа функциялары менен байланышканда маалымат базасында сакталат.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Ойнотуу, комментарийлер, жактыруулар, кийинчерээк көрүү, жазылуулар, эскертмелер, билдирүүлөр, ойнотмо тизмелер жана тил жөндөөлөрү негизги навигация жана эсеп менюсу аркылуу жеткиликтүү.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub – бул бир аккаунттан жаратуучунун мазмунун жүктөө, көрүү, пландаштыруу, башкаруу жана модерациялоо үчүн видео платформа.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub – бул түзүүчүлөр, көрүүчүлөр, коомдоштуктар жана платформа операторлору үчүн курулган бул жайгаштырууда иштеген видео платформа.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub бир платформадан жаратуучу каналдарын, видео жүктөөлөрдү, пландаштырылган жарыялоону, жазылууларды, жорумдарды, ойнотмо тизмелерди, кийинчерээк көрүү, жандуу мазмун барактарын жана башкаруу куралдарын камсыз кылат.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub кирүү сессиялары, API аутентификациясы, CSRF/коопсуздук жүрүм-туруму, тил тандоо, тема тандоо, эсеп менюсунун абалы жана колдонмонун иштеши үчүн зарыл болгон башка функциялар үчүн негизги кукилерди жана серепчи сактагычты колдонот.',
