  'Select a reason' => 'Себебин тандаңыз',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Бир же бир нече видео файлдарды тандаңыз, керектүү маалыматтарды киргизиңиз, категорияны жана тилди тандаңыз, эскизди кошуңуз, көрүнүүнү тандаңыз жана жарыялаңыз. Ири файлдар сервер иштеп баштаганга чейин бөлүктөргө бөлүнүп жүктөлөт.',
  'Send a message and it will be saved for admins.' => 'Билдирүү жөнөтүңүз, ал администраторлор үчүн сакталат.',
