  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Каттоо эсеби, профиль, сырсөз, эскертме, купуялык жана жаратуучунун тандоолору үчүн Кирип, Жөндөөлөрдү колдонуңуз. Жаратуучунун жүктөө жана мазмундагы көйгөйлөрү видеонун аталышын, каналды, браузерди жана жүктөө барагында көрсөтүлгөн иштетүү катасын камтышы керек.',
  'Sign in for account support' => 'Каттоо эсебин колдоо үчүн кириңиз',
