  'Stores language, theme, and interface preferences.' => 'Тилди, теманы жана интерфейстин артыкчылыктарын сактайт.',
  'Studio, playlists, analytics, channels.' => 'Студия, ойнотмо тизмелер, аналитика, каналдар.',
  'Submit a billing or refund message to admin support.' => 'Администратордун колдоосуна эсеп коюу же төлөмдү кайтаруу билдирүүсүн тапшырыңыз.',
