  'Taxonomies' => 'Таксономиялар',
  'Technical issue' => 'Техникалык маселе',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Учурдагы PlayHub API менен интеграциялоо жана жүктөө иш процесси үчүн техникалык эскертүүлөр.',
  'Tell us more about your question or request...' => 'Сурооңуз же өтүнүчүңүз тууралуу кененирээк айтып бериңиз...',
  'Terms of Use' => 'Колдонуу шарттары',
  'The configured' => 'Конфигурацияланган',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Иштеп чыгуучунун бети жандуу Laravel серверине туташкан: маршруттук инвентаризация, маалымат базасынын саны, жүктөө чектөөлөрү жана платформанын метаберилиштери /api/developers\'тен жүктөлөт.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Фронт тандалган тил, тема, ойнотуу кезеги, көрүүнүн жүрүшү жана интерфейстин абалы сыяктуу артыкчылыктарды сактайт, андыктан тажрыйба бет багыттоо жана кайра жүктөө боюнча ырааттуу бойдон калууда.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Иштетүү тапшырмасы аткарууну коддойт, керек болгондо эскиздерди жаратат, коштомо жазууларды сактайт жана иштеп бүткөндө видеолорду даяр деп белгилейт. Келечектеги пландаштырылган видеолор пландоочу аларды чыгармайынча купуя бойдон калат.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Жүктөө системасы маалымат базасы менен камсыздалган, API\'ден категорияларды жана тилдерди колдойт, жүктөлүп берилген видеолорду иштетет, эскиздерди жана коштомо жазууларды сактайт жана пландаштырылган мазмунду чыгаруу убактысына чейин купуя сактайт.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Бул барак PlayHub сеанстар, коопсуздук, артыкчылыктар, ойнотуу жана аутентификацияланган функциялар үчүн кукилерди жана серепчи сактагычты кантип колдонорун түшүндүрөт.',
