  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Түз PlayHub дайындары менен жүктөп бериңиз, көрүңүз, жазылыңыз, модерациялаңыз жана түзүңүз.',
  'Uploaded videos' => 'Жүктөлгөн видеолор',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Жүктөлгөн видеолор ойнотула турган трансляцияларга коддолгон. Иштетүү убактысы файлдын өлчөмүнө, узактыгына, сервердин жүгүнө жана кезектин абалына жараша болот. Жүктөп берүү барагы жана Жаратуучу студиясы видео жазуудан чыныгы иштетүү статусун көрсөтөт.',
  'Uploads, scheduling, and processing are available.' => 'Жүктөп берүү, пландаштыруу жана иштетүү жеткиликтүү.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => '/api/videos, каналдын акыркы чекиттери жана авторлордун иштөө процесстери үчүн аутентификацияланган маршруттарды колдонуңуз.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Администраторлор так мазмун шилтемесин алуу үчүн видеолор жана жорумдар үчүн камтылган отчет аракеттерин колдонуңуз. Администратор панелинин баракчалары колдонуучулар, мазмун, отчеттор, акча табуу, аналитика, колдоо, ролдор жана тутум жөндөөлөрү үчүн жандуу маалымат базасынын дайындарын колдонот.',
  'Use Contact Us' => 'Биз менен байланышыңыз',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Кадимки API сурамдары үчүн JSON жана файлдарды жүктөө үчүн FormData колдонуңуз. Текшерүүнү кыйгап өтпөңүз: категориялар жана тилдер маалымат базасынын идентификаторлору, көрүнүү жалпыга ачык, тизмеленбеген же купуя менен чектелген жана коштомо жазуулар SRT, VTT же TXT файлдарын кабыл алат.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Профилиңизди, коопсуздукту, сырсөзүңүздү, эки факторлуу жеткирүүлөрдү, түзмөктөрдү, артыкчылыктарды жана эскертме параметрлерин жаңыртуу үчүн Жөндөөлөрдү колдонуңуз. Каттоо эсебиңизге кире албасаңыз, кирүү агымын колдонуп, сайттын администраторуна эсептин электрондук почтасын бериңиз.',
  'Use the contact form' => 'Байланыш формасын колдонуңуз',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Администраторлор мазмундун так маалымдамасын алуу үчүн видеолор, жорумдар жана жамааттык посттор боюнча отчеттук аракеттерди колдонуңуз.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Мазмун платформа эрежелерин бузган учурда видеолордо, жорумдарда жана коомдоштук билдирүүлөрүндө отчет аракеттерин колдонуңуз. Бул отчеттор чыныгы мазмун жазуусу менен байланышкан жана жалпы билдирүүгө караганда жакшыраак, анткени администраторлор так нерсени карап чыга алышат.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Аккаунт боюнча жардам, мазмун отчеттору, техникалык маселелер жана администратордун сурамдары үчүн туура PlayHub каналын колдонуңуз.',
  'Video categories' => 'Видео категориялары',
  'Video for everyone. Built for creators and viewers.' => 'Баары үчүн видео. реалдуу платформа маалыматтардан курулган.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Видеону жүктөө, графикти түзүү, эскиздер жана иштетүү маселелери.',
  'Videos, thumbnails, captions, processing.' => 'Видеолор, эскиздер, коштомо жазуулар, иштетүү.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Көрүүчүлөр категорияларды карап, видеолорду издеп, мазмунду көрүп, каналдарга жазыла, кийинчерээк көрүү үчүн видеолорду сактап, жорум калтырып, эскертмелерди алып, тил менен атайын мүмкүнчүлүктөрдү башкара алышат.',
  'Viewing and community help' => 'Көрүү жана коомчулуктун жардамы',
  'Waiting for backend endpoint inventory.' => 'Арткы чектин инвентаризациясы күтүлүүдө.',
  'We’re here to help.' => 'Биз жардам берүү үчүн бул жердебиз.',
  'What is PlayHub?' => 'PlayHub деген эмне?',
  'What PlayHub does' => 'PlayHub эмне кылат',
  'Where do contact messages go?' => 'Байланыш билдирүүлөрү кайда барат?',
  'Why is my video still processing?' => 'Эмне үчүн видеом дагы эле иштетилүүдө?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Ооба. Жүктөп берүү барагындагы жергиликтүү графиктин датасы жана убактысы талаасын колдонуңуз. Backend scheduled_at сактайт, видеону иштетет, датасы келечекте болгон учурда аны купуя сактайт жана Laravel пландоочусу белгиленген убакыттан кийин иштегенде аны чыгарат.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Ооба. Жүктөп берүү боюнча жергиликтүү график талаасын колдонуңуз. Backend пландаштырылган_at сактайт жана графикке убакыт жеткенде иштетилгенден кийин видеону чыгарат.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Сиз конок катары карап жатасыз. Каттоо эсебине тиешелүү куралдарга кирүү үчүн кириңиз.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Каттоо эсебиңиздин далдаштырма маалыматтары, профиль аракети, жүктөлүп берилген мазмун, жорумдар, билдирүүлөр жана каттоо эсебиңизден жасалган бардык жаратуучу же администратор аракеттери үчүн жооптуусуз. Күчтүү сырсөздөрдү колдонуңуз жана эки факторлуу жеткирүү ыкмаларын актуалдуу кармаңыз.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Сиз браузериңиздин жөндөөлөрүнөн браузердин кукилерин жана жергиликтүү сактагычты тазалай аласыз. Негизги сактагычты тазалоо сизден чыгып, тил/тема тандоолорун баштапкы абалга келтирүү, жергиликтүү ойнотуу абалын алып салуу жана кайра кирүүнү талап кылышы мүмкүн.',
  'You receive a response by email.' => 'Сиз электрондук почта аркылуу жооп аласыз.',
  'You’re in control' => 'Сиз көзөмөлдөп турасыз',
  'Your choices' => 'Сиздин тандоолор',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Сиздин билдирүүңүз түздөн-түз веб-сайттын аркасында сакталат жана Колдоо астындагы администратор тактасында көрүнөт.',
  'Your support' => 'Сиздин колдооңуз',
