  'Publish consistently' => 'ырааттуу жарыялоо',
  'Upload your first video and give viewers a clear reason to subscribe.' => 'Биринчи видеоңузду жүктөп берип, көрүүчүлөргө жазылуу үчүн так себеп бериңиз.',
  'Use Shorts for discovery' => 'Ачылыш үчүн Shorts колдонуңуз',
  'Keep testing quick hooks and link viewers to longer videos.' => 'Ыкчам илгичтерди сынап көрүңүз жана көрүүчүлөрдү узунураак видеолорго байланыштырыңыз.',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'Каналыңызды таба элек көрүүчүлөргө жетүү үчүн кыска вертикалдуу видеолорду түзүңүз.',
  'Create short' => 'Кыскача түзүү',
  'Turn comments into loyalty' => 'Комментарийлерди берилгендикке айландырыңыз',
  'Reply to recent comments and turn viewers into returning fans.' => 'Акыркы комментарийлерге жооп берип, көрүүчүлөрдү кайра келген күйөрмандарга айландырыңыз.',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'Кийинки жүктөөңүздө суроо бериңиз жана комментарийлер келгенде тез жооп бериңиз.',
  'View comments' => 'Комментарийлерди көрүү',
