  'Keep strong videos visible and refresh weak titles.' => 'Күчтүү видеолорду көрүнүп туруңуз жана начар аталыштарды жаңыртыңыз.',
  'Explore tools' => 'Куралдар менен таанышыңыз',
  'Open the right workflow fast' => 'Туура иш процессин тез ачыңыз',
  'Upload planner' => 'Жүктөп салгыч',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'Аталышы, тегдери, көрүнүшү жана эскиз кадамдары менен жаңы жүктөөнү баштаңыз.',
  'Shorts studio' => 'Shorts студиясы',
  'Create short videos for faster discovery and mobile viewers.' => 'Тезирээк табуу жана мобилдик көрүүчүлөр үчүн кыска видеолорду түзүңүз.',
  'Content manager' => 'Мазмун менеджери',
  'Review visibility, monetization, comments, and performance in one place.' => 'Көрүнүү, акча табуу, жорумдарды жана майнаптуулукту бир жерден карап көрүңүз.',
  'Analytics review' => 'Аналитика карап чыгуу',
  'Track views, likes, comments, publishing status, and trends.' => 'Көрүүлөрдү, жактырууларды, комментарийлерди, жарыялоо статусун жана тренддерди көзөмөлдөңүз.',
  'Channel profile' => 'Канал профили',
